#include <iostream>
using namespace std;

int findGCD(int a, int b) {
    while (b != 0) {
        int temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

int main() {
    int a, b, n;
    cin >> a >> b >> n;

    while (true) {
        int temp = findGCD(a, n);
        if (n < temp) {
            cout << 1;
            break;
        }
        n -= temp;

        temp = findGCD(b, n);
        if (n < temp) {
            cout << 0;
            break;
        }
        n -= temp;
    }

    return 0;
}

